// Cloudflare Pages Function: every /api/* request goes to the Challenge Arena API.
// Bindings (Cloudflare dashboard > the Pages project > Settings): D1 database `DB`, secret `ARENA_SECRET`.
// The engine file is generated by `node build.js` before Cloudflare bundles this function.
import app from '../../arena/server/app.js';

export async function onRequest({ request, env }) {
  return app.handle(request, env);
}
